'use client';
import { useRef, useState } from 'react';
import { formatCount, useStagger } from '../lib/chart';
import { cx } from '../lib/cx';
import { useControllable, useIsoLayoutEffect, useTween } from '../lib/hooks';
import { Seg } from '../lib/motion';
import '../designme.css';
import './bar-chart.css';

export interface BarChartSeries {
  /** The legend's label, like "Needed review" */
  label: string;
  /** How the hover readout names it, like "reviewed". Defaults to the label in lower case */
  tipLabel?: string;
  /** Defaults to the chart palette: blue, purple, then orange */
  color?: string;
}

export interface BarChartBar {
  /** Under the bar, like "Mon" */
  label: string;
  /** One value per series, stacked from the bottom */
  values: number[];
}

export interface BarChartRange {
  key: string;
  /** On the switch, like "Week" */
  label: string;
  bars: BarChartBar[];
}

export interface BarChartProps {
  /** The name over the big number, like "Agent runs" */
  label: string;
  /** What each part of a stack means, in stacking order */
  series: BarChartSeries[];
  /** One set of bars per range. With more than one, a switch picks between them */
  ranges: BarChartRange[];
  /** Key of the range shown. Leave it out to let the switch change it */
  range?: string;
  /** Defaults to the first range */
  defaultRange?: string;
  onRangeChange?: (key: string) => void;
  /** What the values count, like "runs" in "66 runs" */
  unit?: string;
  /** Writes a value. Defaults to whole numbers like 1,240 */
  format?: (n: number) => string;
  className?: string;
}

// the stack colours the stylesheet gives the first three parts, used for the legend and beyond three
const PALETTE = ['var(--dm-c1)', 'var(--dm-c2)', 'var(--dm-c4)', 'var(--dm-c3)', 'var(--dm-c5)', 'var(--dm-c6)'];

/** Stacked bars that grow in one after another, with a readout on hover and a switch between ranges. */
export function BarChart({ label, series, ranges, range, defaultRange, onRangeChange, unit, format = formatCount, className }: BarChartProps) {
  const [cur, setCur] = useControllable(range, defaultRange ?? ranges[0]?.key ?? '', onRangeChange);
  const count = Math.max(0, ...ranges.map(r => r.bars.length));
  // the bars draw a moment after the chart appears, then redraw left to right on every switch
  const at = useStagger(cur, count, 45, 200);
  const byKey = (k: string | null) => ranges.find(r => r.key === k);
  const shown = byKey(at[0]);
  const sum = (b?: BarChartBar) => b ? b.values.reduce((a, v) => a + v, 0) : 0;
  const total = useTween(shown ? shown.bars.reduce((a, b) => a + sum(b), 0) : 0, 900, 0);

  // the room the bars have, less the label under them
  const ch = useRef<HTMLDivElement>(null);
  const [room, setRoom] = useState(128);
  useIsoLayoutEffect(() => { if (ch.current) setRoom(ch.current.clientHeight - 22); }, []);
  const color = (j: number) => series[j]?.color ?? PALETTE[j % PALETTE.length];

  return (
    <div data-dm="" className={cx('dm-bcx dm-panel', className)}>
      <div className="dm-bcx-h">
        <div><span className="dm-muted">{label}</span><b className="dm-num dm-bcx-v">{format(total)}</b></div>
        {ranges.length > 1 && (
          <Seg className="dm-bcx-rg" label="Range" value={cur} onChange={setCur} options={ranges.map(r => ({ value: r.key, label: r.label }))} />
        )}
      </div>
      <div className="dm-bcx-ch" ref={ch}>
        {Array.from({ length: count }, (_, i) => {
          const r = byKey(at[i]), bar = r?.bars[i], top = r ? Math.max(...r.bars.map(sum)) * 1.08 : 1;
          const tip = shown?.bars[i];
          return (
            <div key={i} className="dm-bcx-b">
              <div className="dm-bcx-tt">
                <b className="dm-num">{tip && `${format(sum(tip))}${unit ? ' ' + unit : ''}`}</b>
                <span>{tip && tip.values.map((v, j) => `${format(v)} ${series[j]?.tipLabel ?? series[j]?.label.toLowerCase() ?? ''}`).join(', ')}</span>
              </div>
              <div className="dm-bcx-st">
                {series.map((_, j) => {
                  const v = bar?.values[j] ?? 0;
                  return <i key={j} style={{ height: bar ? Math.max(v ? 3 : 0, v / top * room) : 0, ...((series[j].color || j > 2) && { background: color(j) }) }} />;
                })}
              </div>
              <div className="dm-bcx-l">{tip?.label}</div>
            </div>
          );
        })}
      </div>
      <div className="dm-bcx-lg dm-muted">{series.map((s, j) => <span key={j}><i style={{ background: color(j) }} />{s.label}</span>)}</div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Bar chart ---------- */
.dm-bcx{padding:14px;display:flex;flex-direction:column;gap:12px}
.dm-bcx-h{display:flex;justify-content:space-between;align-items:flex-start;gap:10px}
.dm-bcx-h>div:first-child{display:flex;flex-direction:column;font-size:12.5px}
.dm-bcx-v{font-size:14px;font-weight:500;letter-spacing:-.02em}
.dm-bcx-rg button{font-size:12px;height:26px;padding:0 10px}
.dm-bcx-ch{display:flex;align-items:flex-end;gap:8px;height:150px;position:relative}
.dm-bcx-b{flex:1;height:100%;display:flex;flex-direction:column;justify-content:flex-end;align-items:stretch;gap:0;position:relative;cursor:default}
.dm-bcx-st{display:flex;flex-direction:column-reverse;gap:2px;border-radius:7px;overflow:hidden;transition:opacity .25s}
.dm-bcx-st i{display:block;height:0;transition:height .7s var(--dm-ease)}
.dm-bcx-st i:nth-child(1){background:var(--dm-c1)}
.dm-bcx-st i:nth-child(2){background:var(--dm-c2)}
.dm-bcx-st i:nth-child(3){background:var(--dm-c4)}
.dm-bcx-ch:hover .dm-bcx-b:not(:hover) .dm-bcx-st{opacity:.4}
.dm-bcx-l{font-size:11px;color:var(--dm-muted);text-align:center;margin-top:6px;height:14px}
.dm-bcx-tt{position:absolute;bottom:calc(100% + 6px);left:50%;transform:translate(-50%,4px);padding:6px 9px;border-radius:10px;background:var(--dm-ink);color:var(--dm-on-ink);font-size:11.5px;white-space:nowrap;opacity:0;pointer-events:none;transition:opacity .2s,transform .25s var(--dm-ease);z-index:2;display:flex;flex-direction:column}
.dm-bcx-tt span{opacity:.75}
.dm-bcx-b:hover .dm-bcx-tt{opacity:1;transform:translate(-50%,0)}
.dm-bcx-b:first-child .dm-bcx-tt{left:0;transform:translate(0,4px)}.dm-bcx-b:first-child:hover .dm-bcx-tt{transform:none}
.dm-bcx-b:last-child .dm-bcx-tt{left:auto;right:0;transform:translate(0,4px)}.dm-bcx-b:last-child:hover .dm-bcx-tt{transform:none}
/* on a phone the bars are too thin for the second and second-last tips to sit centred without passing the edge */
@container (max-width:400px){.dm-bcx-b:nth-child(2) .dm-bcx-tt{left:0;transform:translate(0,4px)}.dm-bcx-b:nth-child(2):hover .dm-bcx-tt{transform:none}.dm-bcx-b:nth-last-child(2) .dm-bcx-tt{left:auto;right:0;transform:translate(0,4px)}.dm-bcx-b:nth-last-child(2):hover .dm-bcx-tt{transform:none}}
.dm-bcx-lg{display:flex;gap:14px;font-size:12px;flex-wrap:wrap}
.dm-bcx-lg span{display:flex;align-items:center;gap:6px}
.dm-bcx-lg i{width:8px;height:8px;border-radius:3px}

